int onoff_reset(struct onoff_manager *mgr,
		struct onoff_client *cli)
{
	if ((mgr == NULL)
	    || (cli == NULL)
	    || (validate_args(mgr, cli) < 0)) {
		return -EINVAL;
	}

	if (mgr->transitions->reset == NULL) {
		return -ENOTSUP;
	}

	k_spinlock_key_t key = k_spin_lock(&mgr->lock);
	uint32_t state = mgr->flags & ONOFF_STATE_MASK;

	if ((state & ONOFF_FLAG_ERROR) == 0U) {
		k_spin_unlock(&mgr->lock, key);
		return -EALREADY;
	}

	sys_slist_append(&mgr->clients, &cli->node);

	if (state != ONOFF_STATE_RESETTING) {
		set_mgr_state(mgr, ONOFF_STATE_RESETTING);
		process_events(mgr, key, 0);
	} else {
		k_spin_unlock(&mgr->lock, key);
	}

	return state;
}
